from questions._util import q

QUESTIONS = [
    q("ctr-security", "medium", "A container mounts /var/run/docker.sock read-only to inspect neighbors. What can it still do?", "Inspect other containers, including their env vars.", "Only list running containers by name and image.", "Nothing, since :ro blocks writes to the socket.", "Read logs, but not inspect container configs.", "Read-only on the socket file does not limit API calls. Inspect shows env vars, which is how many images take passwords, and a writable connection can still start containers."),
    q("ctr-security", "hard", "Why is giving a container the Docker socket a host breakout, even without --privileged?", "It can ask the root daemon to start any container.", "It can read the daemon's TLS keys from the socket.", "It inherits the daemon's capabilities by connecting.", "It can ptrace dockerd through the socket's file descriptor.", "The socket is the daemon's API, and a default daemon runs as root. Projects such as automatic reverse proxies mount it. That is the privilege."),
    q("linux-permissions", "medium", "Capabilities let ping avoid setuid root. Which capability does ping need?", "CAP_NET_RAW", "CAP_NET_ADMIN", "CAP_NET_BIND_SERVICE", "CAP_SYS_ADMIN", "setcap can put cap_net_raw on the ping binary for raw packets. A compromise of ping is then not full root. Many distros now use unprivileged ICMP sockets instead."),
    q("linux-permissions", "easy", "A process only does what an ordinary user can do. Which capabilities does it need?", "None", "CAP_SETUID", "CAP_DAC_OVERRIDE", "Docker's default set", "Capabilities are for privileged actions. Ordinary work needs an empty set."),
    q("ctr-security", "medium", "What does no-new-privileges stop in a non-root container?", "Gaining privilege through setuid binaries.", "Running any binary owned by root.", "Opening any sockets on privileged ports.", "Switching to another non-root user.", "A setuid bash in the image is the demonstration. The flag stops exec from granting extra privilege."),
    q("ctr-security", "hard", "Docker starts a container as root but withholds some capabilities. What does that mean?", "Container root gets a reduced capability set.", "Container root has full capabilities, but seccomp blocks some calls.", "Container root is mapped to an unprivileged host UID.", "Container root loses capabilities only after exec.", "Container root is not host root unless you add capabilities or pass --privileged. User namespace mapping is a separate, opt-in feature."),
    q("k8s-netpol", "medium", "A NetworkPolicy starts selecting a pod that had none. What happens to traffic you did not allow?", "It is denied for the directions the policy covers.", "It is denied in both directions for that pod.", "It is denied for every pod in the namespace.", "It is allowed until a deny rule is added.", "The first matching policy moves that pod off the implicit allow, for ingress, egress, or both as policyTypes says. List the traffic you still want."),
    q("k8s-netpol", "hard", "Your egress NetworkPolicy rules seem to do nothing. What do you check first?", "Whether your CNI enforces egress at all.", "Whether the rules list port 53 for DNS.", "Whether policyTypes is set on the ingress side.", "Whether kube-proxy is in iptables mode.", "Some plugins only enforce ingress. A policy object the plugin does not implement is documentation."),
    q("sec-least", "hard", "etcd for a multi-member cluster listens on 2379 and trusts the Kubernetes CA. Why should etcd have its own dedicated CA?", "Any cert from a trusted CA gets full access.", "etcd rejects certs whose SAN is not a node name.", "The Kubernetes CA cannot sign client certs for etcd.", "A shared CA makes etcd peers trust API clients.", "etcd does not check the certificate's CN or SAN, and there is no further authorization by default. Access is all or nothing once the cert verifies. 2379 is client traffic, 2380 is peer."),
    q("sec-least", "medium", "kubeadm binds etcd to localhost, and a clustered etcd does not. What changed?", "Members must reach each other over the network.", "Clustered etcd stores secrets unencrypted.", "Clustered etcd disables client certificates.", "The API server talks to etcd over UDP.", "2379 and 2380 are then on the network and must be authenticated. etcd holds secrets and service account material, so a listener without a private CA is the cluster."),
    q("k8s-secrets", "medium", "By default, where is a service account token mounted in every container?", "/var/run/secrets/kubernetes.io/serviceaccount/token", "/etc/kubernetes/serviceaccount/token", "/run/secrets/kubernetes.io/token", "/var/lib/kubelet/pods/serviceaccount/kubernetes.io/token", "It is mounted unless you turn automount off. Anyone who can read the container filesystem can present it to the API."),
    q("k8s-rbac", "hard", "Before RBAC was the default, why was the mounted token dangerous?", "It often had cluster-admin rights.", "It never expired and could not be revoked.", "It was shared by every pod in the cluster.", "It was readable by other pods on the node.", "A shell in any pod was a cluster shell. The fix is a current cluster with restrictive RBAC, and no token on workloads that do not call the API."),
    q("sec-pki", "hard", "The Kubernetes CA private key sits on the API server's disk and is valid for about ten years. Why is it a golden ticket?", "It mints client certs for any identity.", "It decrypts every Secret stored in etcd.", "It signs service account tokens for pods.", "It is the key the kubelets use to join.", "Anyone who copies it can be any user until the CA itself is replaced, and certificates cannot be revoked. Service account tokens use a different key."),
    q("sec-pki", "medium", "Why do clusters keep the CA key online instead of offline or in an HSM?", "The control plane signs certs routinely.", "Kubernetes cannot read keys from an HSM.", "The key is rotated every time it starts.", "Offline keys break etcd encryption.", "Installers leave it on the API server for kubelet and CSR signing. Treat those files as the root of cluster identity. A disk copy is a persistent backdoor."),
    q("ctr-rootless", "medium", "In rootless Docker, where is the daemon socket?", "/run/user/<uid>/docker.sock", "/var/run/docker-rootless.sock", "/home/<user>/.docker/docker.sock", "/var/run/docker.sock, user-owned", "The daemon is a user process, so its socket lives in the user's runtime directory. uidmap is the package the install needs for the user namespace."),
    q("ctr-rootless", "hard", "Which sharp edge did rootless Docker 20.10 still have?", "Resource limits need cgroup v2 on the host.", "Images must be rebuilt for rootless mode.", "Volumes cannot be used in rootless mode.", "Containers cannot reach the internet.", "Low ports and ping had extra limits too. Rootless removes host root from the daemon. It does not remove every Linux privilege quirk."),
    q("sec-sbom", "medium", "What can a consumer check when CI signs images with cosign?", "That a trusted key signed that exact digest.", "That the image passed CI's tests and scans.", "That the tag points at the newest build.", "That the registry has not been tampered with.", "The signature says who signed which bytes, nothing more. Do not commit the private key into the repository, even encrypted."),
    q("sec-sbom", "easy", "Why did cosign show up when Docker Content Trust already existed?", "Image signing in CI was still a gap.", "Content Trust had been withdrawn.", "Registries started to require it.", "Content Trust could not sign tags.", "A single binary could sign a built digest. Verification has to be a step you run. A signature nobody checks changes nothing."),
    q("ctr-ports", "medium", "A non-root container binds port 80 on current Docker without CAP_NET_BIND_SERVICE. Which sysctl allows it?", "net.ipv4.ip_unprivileged_port_start", "net.ipv4.ip_local_reserved_ports", "net.ipv4.ip_nonlocal_bind", "net.core.somaxconn", "Docker sets it to 0 in the container's network namespace, not on the host. It is safer than running the process as root to grab a low port."),
    q("ctr-ports", "easy", "Historically, what did binding a port below 1024 require?", "Root or CAP_NET_BIND_SERVICE.", "Root or CAP_NET_ADMIN.", "Root or the docker group membership.", "Root or CAP_NET_RAW.", "That rule is why images ran as root. The sysctl is the way out."),
    q("ctr-security", "hard", "How can a privileged container on cgroup v2 still break out?", "By loading a kernel module.", "By writing release_agent.", "By reading /proc/1/environ.", "By changing its own UID map.", "Privileged includes the right to load modules, and a module runs in the host kernel. The release_agent trick needs cgroup v1."),
    q("sec-runtime", "medium", "What does --privileged add beyond the process being root?", "All capabilities, all devices, no seccomp.", "Host networking and the host's PID space.", "A host mount of / at /host in the container.", "A user namespace mapped to host root.", "Root inside a default container has a reduced capability set. Privileged throws that away and lets it change the host, including loading modules."),
    q("k8s-rbac", "medium", "Anonymous auth on the API server is on by default. Why is that not automatically cluster-admin?", "Anonymous requests still go through RBAC.", "Anonymous requests are read-only by design.", "Anonymous requests are rate-limited hard.", "Anonymous requests only reach /healthz.", "They become system:anonymous in system:unauthenticated and still pass authorization and admission. The dangerous cluster is one that also binds rights to that group."),
    q("k8s-rbac", "hard", "Why is system:public-info-viewer bound to unauthenticated users?", "So version and health endpoints work.", "So kubectl can find the API server.", "So nodes can register before joining.", "So pods can read their own spec.", "It allows a few discovery endpoints without a credential. It is not a grant to create pods. Cryptojacking campaigns look for clusters that went further."),
    q("k8s-rbac", "hard", "kubectl auth can-i --list misses rights that still work. Why?", "It shows RBAC only, not other modes.", "It shows cluster rights, not namespaced.", "It hides rights granted via groups.", "It omits rights on subresources.", "Authorization modes are cumulative, and Node authorization adds rights the list does not show. Check a specific verb with can-i."),
    q("sec-least", "medium", "A container escape hands the attacker the kubelet's credentials. Why do they matter?", "They can read the node's pods and their secrets.", "They can create pods on any node in the cluster.", "They can read every secret in the cluster.", "They can sign new certificates for users.", "The Node authorizer limits the kubelet to objects for its own node, but that still includes its pods' secrets. Keep the node identity narrow."),
    q("sec-image", "hard", "A scanner reports a clean image whose payload is unpacked only when the container starts. Why did it miss it?", "Static scans never run the image.", "The scanner skipped compressed layers.", "The CVE database was out of date.", "The payload's packages had no CPEs.", "A tarball extracted at startup is invisible to a static scan. A clean report is not a guarantee about what the process will assemble."),
    q("sec-image", "medium", "How do scanners and SBOM tools learn what is installed in an image?", "From package databases and known file paths.", "By running the image and tracing its loads.", "From the build logs stored with the image.", "From the image labels set at build time.", "Hide or omit those files and the report changes. A green scan is a statement about the files the tool knew to open."),
    q("k8s-storage", "hard", "A gitRepo volume is deprecated but still accepted. If git is on the node, what can a pod using one do?", "Run commands as root on the node.", "Clone any repo the node can reach.", "Read files from other pods' volumes.", "Write into the node's kubelet config.", "The volume type shells out to git on the host. Baseline Pod Security does not block it. Restricted does. The rights required are create on pods."),
    q("k8s-psa", "medium", "Which Pod Security level actually excludes gitRepo volumes?", "restricted", "baseline", "privileged", "None of them", "baseline still allows the type. Deprecation is not enforcement. If the API accepts the volume, the policy has to reject it."),
    q("k8s-services", "medium", "A kind cluster shows three different address ranges. What are they?", "Node, pod, and Service networks.", "Node, Ingress, and LoadBalancer networks.", "Pod, Service, and etcd peer networks.", "Docker, node, and host networks.", "A packet to a Service IP is not a packet to a pod IP. They are different networks on purpose."),
    q("net-cloud", "easy", "Inside a kind node, what is the address shown by ip addr?", "The node's IP on its Docker network.", "The Service IP of kubernetes.default.", "The first pod IP in the CNI range.", "The host machine's LAN address.", "Pod IPs come from the CNI range. Service IPs come from the service CIDR. Do not debug one with the other's range."),
    q("k8s-rbac", "hard", "A NetworkPolicy blocks your namespace from a pod. Why can the API server proxy still reach it?", "The request comes from the API server, not your pod.", "The proxy subresource is exempt from all RBAC.", "Policies only apply to traffic through a Service.", "The proxy rewrites the source to the pod's namespace.", "The proxy is a second path. Locking pod-to-pod traffic does not lock it. RBAC on pods/proxy is the control."),
    q("k8s-netpol", "medium", "What is curl to 127.0.0.1:8001/api/v1/namespaces/default/pods/<name>:<port>/proxy/?", "kubectl proxy, then the API server reaching the pod.", "kubectl port-forward, then a tunnel to the pod.", "kube-proxy forwarding from the node to the pod.", "A direct connection from your laptop to the pod.", "The echo server sees the API server's address as the client, not yours."),
    q("k8s-debug", "hard", "kubectl debug on a node with the legacy profile can pull with ctr but fails to start a container. Why?", "ctr needs the host's mount namespace.", "The legacy profile has no network access.", "The legacy profile runs as a non-root user.", "ctr needs the API server's credentials.", "containerd assumes the client shares the host mount namespace. Debug profiles grant different rights, and a newer one fixes the mount error."),
    q("k8s-debug", "medium", "Why is the containerd socket not a drop-in for the Docker socket?", "ctr expects the host's mounts beside it.", "The containerd socket is read-only.", "containerd's API needs a client cert.", "ctr cannot start containers by itself.", "A casually mounted containerd socket does not give the same easy breakout. Do not assume it is harmless either."),
    q("k8s-workloads", "easy", "Which command creates a CronJob from the CLI?", "kubectl create cronjob", "kubectl run --schedule", "kubectl create job --cron", "kubectl apply cronjob", "CronJob is its own kind. Pass --schedule in cron syntax and the command after --."),
    q("k8s-rbac", "medium", "A kubeconfig user named operator is created from security.crt and secrecy.key. What did you add?", "A client cert identity with no rights yet.", "A user with the operator ClusterRole.", "A service account named operator.", "A user that can create its own roles.", "The context then points kubectl at that user. Authorization is a separate binding."),
    q("k8s-rbac", "hard", "A ClusterRole named monitor allows every apiGroup, resource, and verb, bound to a service account. What is it?", "cluster-admin under another name.", "Read-only, since verbs exclude write.", "Admin, but only in its own namespace.", "Admin, except for Secrets and RBAC.", "The word monitor does not narrow '*'. A ClusterRoleBinding applies it everywhere. Do not ship that for a monitor."),
    q("iac-modules", "medium", "What is a three-tier Terraform layout with modules pushing you toward?", "Network, compute and data as modules with I/O.", "One root module so state stays in one file.", "A separate repo and pipeline for each tier.", "Each tier in its own workspace of one config.", "Modules are how the same tier is reviewed once and reused per environment, with outputs instead of hard-coded IDs."),
    q("iac-workflow", "medium", "Packer bakes an AMI with Nginx, and Terraform launches from it. What is the point of the split?", "An immutable image instead of configuring after boot.", "Packer can manage state for the AMI it builds.", "Terraform cannot create AMIs on its own.", "Packer images boot faster than any user data.", "Disposable instances come from a baked image plus an autoscaling launch, not from a pet you configured by hand over SSH."),
    q("iac-policy", "medium", "A Rego policy requires S3 versioning and no public access, and apply must fail on a violation. Where does the check sit?", "Against the plan, before apply.", "In the bucket's own policy.", "In a daily AWS Config rule.", "In the S3 Block Public Access.", "Rego is the policy. Terraform is the change. The gate joins them before the bucket exists. The others act after."),
    q("iac-ansible", "medium", "Ansible manages who can SSH to production through a jump host. Why must the playbook be idempotent?", "A rerun must change nothing if access is right.", "A rerun must re-add any keys that were removed.", "A rerun must rotate every key on the host.", "A rerun must only touch hosts that failed.", "The playbook is the access list. A second run that changes more, such as appending keys again, is a bug."),
    q("net-tunnels", "easy", "Developers reach production only through a jump host. What is the host?", "An SSH bastion you harden and audit.", "A VPN concentrator for the whole team.", "A NAT gateway for outbound SSH.", "A proxy that records the screen.", "Direct SSH to every production address is the thing a jump host replaces."),
    q("sec-secrets", "medium", "Why encrypt a database dump before a script uploads it to S3?", "The bucket is another copy of the data.", "S3 rejects unencrypted uploads by default.", "TLS is not used by the S3 CLI by default.", "S3 encryption at rest is not on by default.", "Transport and bucket encryption do not protect against anyone who can read the bucket. Log the backup and the restore. A backup you have not restored is a hope."),
    q("linux-shell", "medium", "Why is a silent cron backup a bad default?", "You find out it broke on restore day.", "Cron kills jobs that print nothing.", "Silent jobs run with a reduced PATH.", "Cron retries silent jobs every hour.", "Check the exit status of the dump and of the upload. Write both to a log you actually read."),
    q("k8s-gitops", "medium", "In an Argo CD setup, what is the controller's job?", "Sync the cluster to git and undo manual edits.", "Build images when a commit lands in git.", "Apply each commit once, then stop watching.", "Push live cluster changes back into git.", "If git is the source, the laptop is not. Self-heal puts manual edits back."),
    q("k8s-helm", "medium", "You install a Helm release in a namespace, with values for replicas and image tag. What is the model?", "Chart is the template. Values make the deploy.", "Values override the chart's templates.", "Releases are scoped to the chart's repository.", "The image tag belongs in Chart.yaml.", "Pin the tag in values and upgrade the release when it changes. Do not edit the live Deployment and lose the source."),
    q("k8s-services", "medium", "What does Istio add in front of a Kubernetes service?", "mTLS and traffic routing policy.", "Pod autoscaling on request rate.", "A replacement for the Service object.", "DNS names for each pod's IP.", "The mesh is another hop. Know whether TLS stops at the gateway or continues to the pod."),
    q("sec-vault", "medium", "An app reads a secret from Vault at start. How should it authenticate?", "With AppRole or workload identity.", "With a root token from the AMI.", "With a token from Terraform output.", "With a static token in the image.", "Root is for bringing Vault up. Workloads get a lease and a policy for their one path."),
    q("ctr-multistage", "easy", "What does a multi-stage Docker build give the runtime image?", "The artifact, without the toolchain.", "The toolchain, without the source.", "The source, without the cache.", "The cache, without the artifact.", "The final FROM is a small base. COPY --from brings the binary across and leaves the compiler and build credentials behind."),
    q("ctr-compose", "medium", "The app starts before the database accepts connections. What does depends_on alone do?", "Starts the database container first.", "Waits for the database's port to open.", "Restarts the app if the database fails.", "Runs the database's healthcheck first.", "A process with a PID is not a database that finished init. Add a healthcheck and condition: service_healthy."),
    q("cicd-actions", "medium", "A GitHub Actions workflow builds and pushes an image on push to main. What should it not do?", "Use a long-lived cloud admin key.", "Pin the actions it uses by SHA.", "Run the tests before the push.", "Push to a registry in its account.", "The workflow is a principal. Scope it to the one registry repository it pushes."),
    q("sec-pipeline", "medium", "Container security is often split into build, ship, and run. What does a CI-only scan cover?", "Build only.", "Build and ship.", "Ship and run.", "All three.", "Ship needs registry controls and signatures. Run needs admission and runtime policy. The gap is the scanned and admitted images being different digests."),
    q("sec-image", "medium", "Vulnerability management is a lifecycle. What step do people skip?", "An owner, a due date, and verifying the fix.", "Deduplicating findings across scanners.", "Scoring each finding with CVSS first.", "Scanning again with a second tool.", "A finding without an owner is a list. Verification is a rescan of the thing you shipped."),
    q("sec-sbom", "hard", "Supply-chain security adds provenance attestations on top of an SBOM. What is an attestation?", "A signed claim about how it was built.", "A signed list of the packages inside.", "A signed report of the CVEs it has.", "A signed approval to deploy it.", "You can have a bill of materials and still not know which builder produced it. The attestation is that claim."),
    q("k8s-psa", "easy", "In Kubernetes security, what does the admission layer do?", "Rejects bad objects before they are stored.", "Decides which users may call the API.", "Detects bad behavior in running pods.", "Isolates pods from each other's traffic.", "RBAC decides who may ask. Admission, where Pod Security and policy engines sit, decides whether the object is acceptable."),
    q("sec-secrets", "medium", "Rotation is part of storing a secret. What is a secret you cannot rotate without a manual redeploy?", "A design flaw to fix.", "Fine if stored encrypted.", "Fine if access is logged.", "Fine if it never expires.", "The app should fetch the current value and accept a new one. Leakage includes env dumps, crash logs, and Terraform state, so rotation must reach every copy."),
    q("cloud-iam", "medium", "Why does IAM separate users and roles?", "People and workloads assume roles for tasks.", "Users hold policies. Roles cannot hold them.", "Roles are for people. Users are for workloads.", "Users work across accounts. Roles cannot.", "A long-lived user key is not how a workload should call an API. Policy is the allow. The principal is who presents it."),
    q("iac-policy", "easy", "What is IaC security, in practice?", "Policy checks on the plan before apply.", "Scanning the cloud for drift each night.", "Encrypting Terraform state at rest.", "Signing Terraform modules before use.", "The misconfiguration is cheapest to stop in the diff, where a public bucket becomes a failed change."),
    q("obs-logs", "medium", "Treat cloud logging as detection. What does a useful pipeline do?", "Ships audit events where attackers cannot delete them.", "Keeps every log line on the instance for a year.", "Samples audit events to keep the volume low.", "Sends only error-level events to the SIEM.", "If the attacker can delete the only copy, you do not have detection. Keep enough identity to say who changed what."),
    q("sec-bench", "medium", "kube-hunter and kube-bench are often listed together. How do they differ?", "kube-bench checks CIS config. kube-hunter probes attacks.", "kube-hunter checks CIS config. kube-bench probes attacks.", "kube-bench scans images. kube-hunter scans manifests.", "kube-bench audits RBAC. kube-hunter audits policies.", "One is a configuration review. The other actively looks for exposure, so run it only against a cluster you own."),
    q("sec-secrets", "easy", "What do git-secrets and similar hooks do?", "Block commits that contain credentials.", "Encrypt files that contain credentials.", "Remove credentials from git history.", "Rotate credentials found in commits.", "A hook on the laptop is early. It is not a guarantee once the secret is already in history."),
    q("sec-audit", "medium", "Why is osquery useful for threat hunting?", "You can query a fleet's live state, repeatedly.", "It blocks processes that match known threats.", "It ships logs from every host to one SIEM.", "It records every syscall for later replay.", "A query you can rerun is how a one-off incident check becomes a control."),
    q("iac-policy", "hard", "Checkov and InSpec are both security testing tools. How do they split?", "Checkov reads IaC. InSpec checks a system's state.", "Checkov checks a system. InSpec reads IaC files.", "Checkov uses Rego. InSpec uses Sentinel policies.", "Checkov runs after apply. InSpec runs before it.", "Use the one that sees the artifact you are about to ship. A passing Checkov does not prove the host matches the profile."),
]
